"""Local configuration editor/report viewer; no remote execution or market feed."""
import json
from pathlib import Path

def build(config,out):
    data=json.dumps(config).replace('<','\\u003c')
    html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stellar Forge Reference v.1.1</title>
<style>body{font:16px system-ui;background:#0c1423;color:#e3ecfa;margin:0}main{max-width:1080px;margin:auto;padding:24px}h1{font-size:30px}.banner{background:#402c14;padding:15px;border-left:5px solid #ffc267}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:15px}section{background:#172439;padding:18px;border-radius:12px;margin-top:18px}label{display:block;margin:12px 0}input,select,button,textarea{font:inherit;padding:9px;border:1px solid #7890ae;border-radius:6px;background:#f4f7fc;color:#12213a;max-width:100%;box-sizing:border-box}input[type=number],select{width:100%}button{cursor:pointer;background:#bce5f6;font-weight:650}textarea{width:100%;height:280px;font:13px monospace}pre{white-space:pre-wrap;overflow-wrap:anywhere}small{color:#c0d0e6}#error{color:#ffb7ac}svg{background:#eff5ff;width:100%;height:190px}a{color:#a2e5ff}</style>
<main><h1>Stellar Forge Reference v.1.1</h1><p>Local experiment configuration and report viewer</p><div class="banner"><strong>SYNTHETIC MECHANICAL BENCHMARK — NOT A FUSION PREDICTION.</strong><br>Frequency changes affect a forced single-mode response only. No acoustic-to-nuclear gain is implemented. Location is metadata until measured geometry and transfer functions exist.</div>
<div class="grid"><section><h2>Acoustic experiment</h2><label>Actuation location<select id="location"><option>pitcher</option><option>catcher</option><option>support</option><option>beamline_component</option></select></label><label>Preset<select id="preset"><option>FM</option><option>TONE</option><option>CHIRP</option><option>OFF</option><option>SHAM</option><option>REFERENCE</option></select></label><p><small>Presets supply synthetic settings for software testing. They are not recommended laboratory frequencies or validated controls.</small></p><div id="fields"></div><button id="apply">Apply acoustic settings to configuration</button></section>
<section><h2>Run configuration</h2><label>Load configuration JSON <input type="file" id="load" accept=".json"></label><textarea id="config" aria-label="Complete experiment JSON"></textarea><p><button id="download">Download configuration</button></p><p>Run locally with the installed package:</p><pre>stellar-forge run your_config.json --out runs/new_run</pre><p>Source audit paths are relative to that JSON. No numerical engine runs in this page. Edit inputs, export, run the CLI and load RESULTS.json below.</p><p id="error" role="alert"></p></section></div>
<section><h2>Inspect a completed run</h2><label>Load RESULTS.json <input type="file" id="results" accept=".json"></label><pre id="summary">No run loaded. Unknown results are not zero.</pre><svg id="plot" viewBox="0 0 900 190" role="img" aria-label="Synthetic acoustic displacement versus time"><text x="20" y="35">No mechanical trace loaded.</text></svg><p><small>Displacement is not stress, fatigue or fusion enhancement. SHAM excludes intended coherent forcing here; actual thermal and electromagnetic effects remain unmodeled. Stored settings include driver wall energy, which must fit within the declared auxiliary energy bill.</small></p></section></main>
<script id="starter" type="application/json">__CONFIG__</script><script>
'use strict';
const $=id=>document.getElementById(id);const numeric=['carrier_Hz','deviation_Hz','modulation_Hz','phase_rad','acceleration_m_s2','duration_s','start_before_shot_s','samples','mode_Hz','damping_ratio','driver_wall_J'];
for(const k of numeric){const label=document.createElement('label');label.textContent=k;const input=document.createElement('input');input.type='number';input.step='any';input.id=k;label.append(input);$('fields').append(label);}
function sync(c){$('config').value=JSON.stringify(c,null,2);if(c.acoustic){$('location').value=c.acoustic.location;for(const k of numeric)$(k).value=c.acoustic[k];}}
sync(JSON.parse($('starter').textContent));
function error(e){$('error').textContent=e.message;}
function apply(){const c=JSON.parse($('config').value);const p=$('preset').value;const a={location:$('location').value,arm:['OFF','SHAM','REFERENCE'].includes(p)?p:'ON',waveform:p==='CHIRP'?'linear_chirp':p==='FM'?'sinusoidal_FM':'tone'};for(const k of numeric){if($(k).value.trim()==='')throw Error('Missing '+k);a[k]=Number($(k).value);if(!Number.isFinite(a[k]))throw Error('Invalid '+k);}if(a.waveform==='tone')a.deviation_Hz=0;if(['OFF','REFERENCE'].includes(a.arm))a.driver_wall_J=0;c.acoustic=a;$('config').value=JSON.stringify(c,null,2);$('error').textContent='';return c;}
$('apply').onclick=()=>{try{apply();}catch(e){error(e);}};
$('preset').onchange=()=>{if($('preset').value==='TONE')$('deviation_Hz').value=0;};
$('download').onclick=()=>{try{const c=apply();const blob=new Blob([JSON.stringify(c,null,2)+'\\n'],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='stellar_forge_config.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}catch(e){error(e);}};
$('load').onchange=async e=>{try{const c=JSON.parse(await e.target.files[0].text());sync(c);const a=c.acoustic;if(a)$('preset').value=a.arm==='ON'?(a.waveform==='sinusoidal_FM'?'FM':a.waveform==='linear_chirp'?'CHIRP':'TONE'):a.arm;$('error').textContent='';}catch(x){error(x);}};
$('results').onchange=async e=>{try{const r=JSON.parse(await e.target.files[0].text());const a=r.integrated_extensions?.acoustic;$('summary').textContent=JSON.stringify({status:r.status,physical_prediction:r.physical_prediction,scientific_outcome:r.scientific_outcome,acoustic_status:a?.status,location:a?.configuration?.location,peak_displacement_m:a?.peak_displacement_m,net_energy_scenario_J:r.energy_scenario?.net_electric_J,energy_scope:r.energy_scenario?.connection_to_transport,economic_scenario:r.economic_scenario,capital:r.capital},null,2);if(a?.trace?.length){const trace=a.trace;const xs=trace.map(x=>x[0]),ys=trace.map(x=>x[2]);if(![...xs,...ys].every(Number.isFinite))throw Error('Nonfinite trace');const lo=Math.min(...xs),hi=Math.max(...xs);const ymax=Math.max(...ys.map(Math.abs),1e-30);const pts=trace.map((x,i)=>(30+840*(x[0]-lo)/(hi-lo||1))+','+(95-65*ys[i]/ymax)).join(' ');$('plot').replaceChildren();const ns='http://www.w3.org/2000/svg';const line=document.createElementNS(ns,'polyline');line.setAttribute('points',pts);line.setAttribute('fill','none');line.setAttribute('stroke','#1b67a5');line.setAttribute('stroke-width','2');$('plot').append(line);const label=document.createElementNS(ns,'text');label.setAttribute('x','30');label.setAttribute('y','180');label.textContent='time '+lo.toPrecision(3)+' to '+hi.toPrecision(3)+' s; displacement ±'+ymax.toPrecision(3)+' m (synthetic)';$('plot').append(label);}}catch(x){error(x);}};
</script></html>'''.replace('__CONFIG__',data)
    with Path(out).open('x') as f:f.write(html)
